  Site: { color: '#1f5f5b', required: ['location'] },
  Workcenter: { color: '#2f7d6d', required: [] },
  Line: { color: '#4b9b8a', required: [] },
  Machine: { color: '#c0603a', required: ['vendor'] },
  Process: { color: '#7b5ea7', required: [] },
  Material: { color: '#b88a1b', required: [] },
